"""Load builder-defined LLM tools for skills.

:func:`load_tools_for_skill_catalog`
    Loads tools for every skill in a :class:`~rasa.mantle.skills.catalog.SkillCatalog`
    from a directory on disk. Tools are discovered from, in resolution order:

    1. **Skill-local** — ``skills/<skill_id>/tools.py`` and every
       ``skills/<skill_id>/tools/*.py`` (auto-discovered, no declaration).
    2. **Shared** — ``@tool`` funcs from ``tools/*.py`` at the agent (snapshot)
       root, but **only those the skill declares** (its ``logic.tools`` / flow
       tools — the current stand-in for ``import_tools``). A shared tool is
       never added to a skill that does not reference it, so it cannot be
       dispatched from an unrelated skill. Within a skill, a ``tools/*.py``
       definition shadows a same-named ``tools.py`` one (logged).

    Skill-local tools take precedence over declared shared tools on a name
    collision. The MCP tier (external servers) is handled separately.

    While a tool module is imported the snapshot root is on ``sys.path``, so
    shared project code is importable depth-independently from any tool
    location: ``from lib.helpers import x`` works the same in
    ``skills/<id>/tools.py``, ``skills/<id>/tools/*.py``, and a shared
    ``tools/*.py``. Do such imports at module top level — the snapshot root is
    only importable during tool loading, not later at dispatch time. ``lib``
    modules imported this way are re-imported on the next load, so a
    hot-swapped model picks up changed ``lib/`` code.

    A tool module that fails to import raises :class:`ToolLoadingError` — a
    broken file must fail the model load loudly instead of silently dropping
    every tool it defines.

The returned dict is keyed by **skill ID**, with each value being a nested
dict of ``{tool_name: func}``. This scoped structure avoids name collisions
when two skills happen to define tools with the same function name.
"""

from __future__ import annotations

import importlib.util
import sys
from contextlib import contextmanager
from pathlib import Path
from typing import Any, Callable, Dict, Iterator

import structlog

from rasa.mantle.llm.tool_schemas import FRAMEWORK_TOOL_NAMES
from rasa.mantle.orchestration.memory_validation_tools import is_memory_validation_tool
from rasa.mantle.skills.catalog import load_default_skill_catalog
from rasa.mantle.snapshot_lib import (
    evict_snapshot_lib_modules,
    record_snapshot_lib_modules,
)
from rasa.shared.exceptions import RasaException

structlogger = structlog.get_logger(__name__)

TOOLS_FILE_NAME = "tools.py"
TOOLS_DIR_NAME = "tools"
_SKILLS_SNAPSHOT_PATH = "mantle_snapshot/skills"


class ToolLoadingError(RasaException):
    """A tool module in the model archive could not be imported."""


@contextmanager
def _importable_snapshot_root(snapshot_root: Path) -> Iterator[None]:
    """Put *snapshot_root* on ``sys.path`` so tool modules can ``import lib``.

    This makes ``lib/`` imports depth-independent — the same ``from lib import
    x`` works for every tool location. New top-level ``lib`` modules imported
    while the context is active are recorded for eviction on the next load.
    """
    path_entry = str(snapshot_root)
    already_present = path_entry in sys.path
    if not already_present:
        sys.path.insert(0, path_entry)
    try:
        yield
    finally:
        if not already_present:
            try:
                sys.path.remove(path_entry)
            except ValueError:
                structlogger.debug(
                    "mantle.tool_loader.sys_path_entry_already_removed",
                    path_entry=path_entry,
                )
        record_snapshot_lib_modules()


def _load_tool_module(
    module_path: Path, module_name: str, snapshot_root: Path
) -> Dict[str, Callable]:
    """Import a single ``.py`` file and return its ``@tool``-decorated callables.

    Raises:
        ToolLoadingError: When the module cannot be imported. A broken tool
            file fails the load loudly — silently dropping its tools would
            surface much later as confusing "Unknown tool" dispatch errors.
    """
    spec = importlib.util.spec_from_file_location(module_name, module_path)
    if spec is None or spec.loader is None:
        raise ToolLoadingError(f"Unable to create an import spec for {module_path}.")

    module = importlib.util.module_from_spec(spec)
    try:
        # TODO(security): exec_module runs arbitrary Python from the model archive
        # without sandboxing.  This is safe when archives are produced by trusted
        # CI pipelines, but provides no protection against tampered archives.
        # Tracked in ENG-2931: subprocess isolation or archive signing.
        with _importable_snapshot_root(snapshot_root):
            spec.loader.exec_module(module)
    except Exception as exc:
        raise ToolLoadingError(
            f"Failed to import tool module {module_path}: {exc}"
        ) from exc

    return {
        name: obj
        for name, obj in vars(module).items()
        if callable(obj) and hasattr(obj, "_tool_description")
    }


def _merge_tools(
    into: Dict[str, Callable],
    new: Dict[str, Callable],
    source: str,
) -> None:
    """Merge *new* tool funcs into *into*, logging a warning on name collision.

    Later sources overwrite earlier ones; callers order calls so the intended
    precedence wins (e.g. skill-local merged after shared).
    """
    for name, func in new.items():
        if name in into:
            structlogger.warning(
                "mantle.tool_loader.duplicate_tool_name",
                tool_name=name,
                source=source,
            )
        into[name] = func


def _load_tools_from_dir(
    tools_dir: Path, module_prefix: str, snapshot_root: Path
) -> Dict[str, Callable]:
    """Import every ``*.py`` under *tools_dir* and merge their ``@tool`` funcs.

    Files are imported in sorted order; ``__init__.py`` is skipped. A tool name
    defined in two files within the same directory is a name collision (logged).
    """
    funcs: Dict[str, Callable] = {}
    for module_path in sorted(tools_dir.glob("*.py")):
        if module_path.name == "__init__.py":
            continue
        module_name = f"{module_prefix}_{module_path.stem}"
        _merge_tools(
            funcs,
            _load_tool_module(module_path, module_name, snapshot_root),
            str(module_path),
        )
    return funcs


def load_tools_for_flow(
    flow_id: str,
    snapshot_skills_root: Path,
) -> Dict[str, Callable]:
    """Return the skill-local ``@tool`` funcs for *flow_id*.

    Discovers tools from both ``<root>/<flow_id>/tools.py`` (single file) and
    ``<root>/<flow_id>/tools/*.py`` (folder); the folder may split tools across
    files. Only functions decorated with
    :func:`~rasa.mantle.tools.decorator.tool` are included. Tools whose names
    collide with engine-owned framework tools (see
    :data:`~rasa.mantle.llm.tool_schemas.FRAMEWORK_TOOL_NAMES`) raise
    :class:`ValueError` so they cannot shadow runtime dispatch. Returns an
    empty dict when the skill declares no tools.

    Raises:
        ValueError: When a decorated tool reuses a reserved framework tool name.

    Args:
        flow_id: The skill's ID string, used as the subdirectory name under
            *snapshot_skills_root*.
        snapshot_skills_root: Path to the ``skills/`` directory extracted from
            the model archive.

    Returns:
        Mapping of ``{function_name: function}`` for all tool-decorated
        callables found for the skill, or ``{}`` when none exist.
    """
    # Guard against path traversal: IDs must not contain path separators.
    if ".." in flow_id or "/" in flow_id or "\\" in flow_id:
        structlogger.warning(
            "mantle.tool_loader.load_tools_for_flow.unsafe_flow_id",
            flow_id=flow_id,
        )
        return {}

    snapshot_root = snapshot_skills_root.parent
    skill_dir = snapshot_skills_root / flow_id
    funcs: Dict[str, Callable] = {}

    single_file = skill_dir / TOOLS_FILE_NAME
    if single_file.is_file():
        _merge_tools(
            funcs,
            _load_tool_module(single_file, f"_mantle_tools_{flow_id}", snapshot_root),
            str(single_file),
        )

    tools_dir = skill_dir / TOOLS_DIR_NAME
    if tools_dir.is_dir():
        _merge_tools(
            funcs,
            _load_tools_from_dir(tools_dir, f"_mantle_tools_{flow_id}", snapshot_root),
            str(tools_dir),
        )

    reserved = sorted(name for name in funcs if name in FRAMEWORK_TOOL_NAMES)
    if reserved:
        raise ValueError(
            f"Skill {flow_id!r} defines builder tool(s) {reserved} that reuse "
            "reserved framework tool names. Rename them — reserved names are: "
            f"{sorted(FRAMEWORK_TOOL_NAMES)}."
        )

    structlogger.debug(
        "mantle.tool_loader.load_tools_for_flow.loaded",
        flow_id=flow_id,
        tool_names=list(funcs.keys()),
    )
    return funcs


def load_shared_tools(snapshot_root: Path) -> Dict[str, Callable]:
    """Return the shared ``@tool`` funcs from the agent-root ``tools/`` folder.

    Args:
        snapshot_root: The snapshot root (``mantle_snapshot/``), i.e. the
            parent of the ``skills/`` directory. Shared tools live under
            ``<snapshot_root>/tools/*.py``.

    Returns:
        Mapping of ``{function_name: function}`` for all shared tool-decorated
        callables, or ``{}`` when there is no shared ``tools/`` folder.

    Raises:
        ValueError: When a shared tool reuses a reserved framework tool name.
    """
    tools_dir = snapshot_root / TOOLS_DIR_NAME
    if not tools_dir.is_dir():
        return {}
    funcs = _load_tools_from_dir(tools_dir, "_mantle_shared_tools", snapshot_root)
    reserved = sorted(name for name in funcs if name in FRAMEWORK_TOOL_NAMES)
    if reserved:
        raise ValueError(
            f"The shared tools/ folder defines builder tool(s) {reserved} that "
            "reuse reserved framework tool names. Rename them — reserved names "
            f"are: {sorted(FRAMEWORK_TOOL_NAMES)}."
        )
    # ``set_<field>`` is reserved for a skill's auto-generated collect setter,
    # which dispatch routes *before* a registered tool of the same name. A
    # cross-skill shared tool must not claim that prefix and shadow collection
    # in every skill that declares it — drop it at load with a warning.
    for name in [name for name in funcs if name.startswith("set_")]:
        structlogger.warning(
            "mantle.tool_loader.shared_tool.reserved_prefix",
            tool_name=name,
        )
        del funcs[name]
    structlogger.debug(
        "mantle.tool_loader.load_shared_tools.loaded",
        tool_names=list(funcs.keys()),
    )
    return funcs


def load_tools_for_skill_catalog(
    skill_catalog: Any,
    snapshot_skills_root: Path,
    *,
    defaults_skills_root: Path | None = None,
) -> Dict[str, Dict[str, Callable]]:
    """Load tool functions for all skills in a :class:`SkillCatalog`.

    Each skill's registry is the subset of shared agent-root tools it
    **declares** (``logic.tools`` / flow tools), overlaid with bundled default
    tools (when ``skill.is_default`` is true or the skill ID is a known bundled
    default) and skill-local snapshot tools.  Later sources shadow earlier ones
    on a name collision (logged).  Bundled default tools load from
    *defaults_skills_root* when a project skill reuses a bundled default skill
    ID without shipping ``tools.py`` — snapshot tools are merged on top and
    override bundled tools with the same name.

    Args:
        skill_catalog: A :class:`~rasa.mantle.skills.catalog.SkillCatalog`
            instance.  Typed as ``Any`` to avoid a hard circular import at the
            module level; callers always pass a ``SkillCatalog``.
        snapshot_skills_root: Path to the extracted ``skills/`` directory.
        defaults_skills_root: Optional path to bundled default skills (e.g.
            ``rasa/mantle/default_skills``).  Omitted when no defaults apply.

    Returns:
        Mapping ``{skill_id: {tool_name: func}}``.  Skills with no tools map to
        an empty inner dict.
    """
    # A fresh load must not reuse ``lib`` modules cached from a previously
    # loaded model (hot swap) — evict them so tool imports re-read this
    # snapshot's ``lib/``.
    evict_snapshot_lib_modules()

    shared_tools = load_shared_tools(snapshot_skills_root.parent)

    # Shared memory validation tools from the agent root are merged onto every
    # skill, not only skills that declare them. They are engine-invoked and never
    # exposed to the LLM (see ``visible_custom_tool_names``), so making them
    # ubiquitous is safe.
    shared_memory_validation_tools = {
        name: func
        for name, func in shared_tools.items()
        if is_memory_validation_tool(name)
    }

    result: Dict[str, Dict[str, Callable]] = {}
    bundled_default_skill_ids: frozenset[str] = frozenset()
    if defaults_skills_root is not None:
        bundled_default_skill_ids = frozenset(load_default_skill_catalog().skills)

    for skill_id, skill in skill_catalog.skills.items():
        # TODO: Validate ``routing.is_default`` at train/validate time — only
        # bundled default skills may set it; project skills cannot set
        # ``is_default`` to true.
        declared = skill_catalog.declared_tool_names(skill_id)
        funcs: Dict[str, Callable] = {
            name: func for name, func in shared_tools.items() if name in declared
        }
        # A skill-local tool of the same name (merged below) still wins.
        _merge_tools(
            funcs, shared_memory_validation_tools, "shared:memory_validation_tools"
        )
        if defaults_skills_root is not None and (
            skill.is_default or skill_id in bundled_default_skill_ids
        ):
            _merge_tools(
                funcs,
                load_tools_for_flow(skill_id, defaults_skills_root),
                f"bundled:{skill_id}",
            )
        _merge_tools(
            funcs,
            load_tools_for_flow(skill_id, snapshot_skills_root),
            f"skill:{skill_id}",
        )
        result[skill_id] = funcs

    structlogger.info(
        "mantle.tool_loader.load_tools_for_skill_catalog.finished",
        skill_count=len(result),
        shared_tool_count=len(shared_tools),
        skills_with_tools=[sid for sid, funcs in result.items() if funcs],
    )
    return result
